  "few_shot_examples": [
    {
      "input": "Paper: 'Attention Is All You Need' by Vaswani et al. (2017). Introduces Transformer architecture using self-attention mechanism.",
      "chain_of_thought": "1. Identifikasi topik: Transformer architecture\n2. Ekstrak insight: Self-attention menggantikan RNN/LSTM\n3. Tentukan kategori: AI/ML - Architecture\n4. Tentukan confidence: High (paper seminal)\n5. Generate tags: transformer, attention, nlp, deep-learning",
      "output": {
        "source": "Attention Is All You Need (Vaswani 2017)",
        "insight": "Transformer architecture menggunakan self-attention mechanism yang memungkinkan paralelisasi penuh, menggantikan recurrent/convolutional networks untuk sequence modeling",
        "confidence": 0.95,
        "category": "AI/ML - Architecture",
        "tags": ["transformer", "attention", "nlp", "deep-learning", "seminal"],
        "seci_phase": "externalization",
        "actionable": true,
        "summary": "Transformer menggunakan self-attention untuk paralelisasi penuh dalam sequence modeling"
      }
    },
    {
      "input": "Paper: 'BERT: Pre-training of Deep Bidirectional Transformers' by Devlin et al. (2018). BERT uses masked language modeling for pre-training.",
      "chain_of_thought": "1. Identifikasi topik: BERT pre-training\n2. Ekstrak insight: Masked LM + Next Sentence Prediction\n3. Tentukan kategori: AI/ML - NLP\n4. Tentukan confidence: High (widely adopted)\n5. Generate tags: bert, pre-training, masked-lm, bidirectional",
      "output": {
        "source": "BERT: Pre-training of Deep Bidirectional Transformers (Devlin 2018)",
        "insight": "BERT menggunakan Masked Language Modeling (MLM) dan Next Sentence Prediction (NSP) untuk pre-training bidirectional representations, mencapai state-of-the-art di 11 NLP tasks",
        "confidence": 0.92,
        "category": "AI/ML - NLP",
        "tags": ["bert", "pre-training", "masked-lm", "bidirectional", "nlp"],
        "seci_phase": "externalization",
        "actionable": true,
        "summary": "BERT pre-training dengan MLM+NSP mencapai SOTA di 11 NLP tasks"
      }
    }
  ],
  "output_schema": {
    "type": "object",
    "required": ["source", "insight", "confidence", "category", "tags", "seci_phase", "actionable", "summary"],
    "properties": {
      "source": {"type": "string", "description": "Sumber konten (paper, URL, penulis)"},
      "insight": {"type": "string", "description": "Insight pengetahuan yang diekstrak (1-2 kalimat)"},
      "confidence": {"type": "number", "minimum": 0, "maximum": 1, "description": "Tingkat keyakinan (0.0-1.0)"},
      "category": {"type": "string", "description": "Kategori: AI/ML - Forecasting/Estimasi/Klasifikasi/Clustering/Asosiasi"},
      "tags": {"type": "array", "items": {"type": "string"}, "description": "Tags untuk pencarian"},
      "seci_phase": {"type": "string", "enum": ["socialization", "externalization", "combination", "internalization"], "default": "externalization"},
      "actionable": {"type": "boolean", "description": "Apakah insight bisa ditindaklanjuti"},
      "summary": {"type": "string", "description": "Ringkasan singkat untuk Kurator (maks 100 karakter)"}
    }
  },
  "constraints": [
    "Output HANYA JSON valid, tanpa markdown ```json``` atau teks lain",
    "Gunakan Chain-of-Thought di system prompt, bukan di output",
    "Confidence harus antara 0.0 dan 1.0",
    "Tags minimal 3, maksimal 8",
    "Summary maksimal 100 karakter"
  ],
  "crispdm_mapping": {
    "fase": "Data Understanding & Preparation",
    "activity": "Ekstraksi insight dari literature/academic sources"
  },
  "model_preference": {
    "primary": "llama3.2:3b-instruct-q4_K_M",
    "fallback": "phi3:mini-instruct-q4_K_M",
    "timeout_seconds": 120
  }
}
"}

